1	import type { ReactNode } from "react";
2	import { Progress } from "./Progress";
3	import type { Tone } from "./Badge";
4	
5	/* A single number the customer is being asked to understand. The rules that
6	   make these readable at a glance and which every ad-hoc version got wrong:
7	   the LABEL is small and quiet, the VALUE is large and tabular, the unit is
8	   subordinate to the value rather than the same size, and any bar sits below
9	   both rather than beside them. */
10	export function Stat({
11	  label,
12	  value,
13	  unit,
14	  detail,
15	  bar,
16	  tone,
17	  className = "",
18	}: {
19	  label: string;
20	  value: ReactNode;
21	  unit?: string;
22	  detail?: ReactNode;
23	  /** `{ value, max }` renders a usage bar that recolours as it fills. */
24	  bar?: { value: number; max: number };
25	  tone?: Tone;
26	  className?: string;
27	}) {
28	  return (
29	    <div className={`flex flex-col ${className}`}>
30	      <span className="k-label">{label}</span>
31	      <span className="mt-2 flex items-baseline gap-1.5">
32	        <span className="k-num text-2xl leading-none font-semibold tracking-tight text-ink">
33	          {value}
34	        </span>
35	        {unit != null && <span className="text-[0.8125rem] text-ink-3">{unit}</span>}
36	      </span>
37	      {bar != null && (
38	        <Progress
39	          className="mt-3"
40	          size="sm"
41	          value={bar.value}
42	          max={bar.max}
43	          tone={tone}
44	          label={label}
45	        />
46	      )}
47	      {detail != null && <span className="mt-2 text-xs text-ink-2">{detail}</span>}
48	    </div>
49	  );
50	}
51	
52	/** Row of stats inside one panel, divided rather than boxed separately — four
53	    individual cards for four related numbers reads as four unrelated things. */
54	export function StatRow({ children, className = "" }: { children: ReactNode; className?: string }) {
55	  return (
56	    <div
57	      className={`grid grid-cols-2 gap-x-6 gap-y-6 lg:grid-cols-4 lg:divide-x lg:divide-hair ${className}`}
58	    >
59	      {children}
60	    </div>
61	  );
62	}
