1	import type { Tone } from "./Badge";
2	
3	const FILL: Record<Tone, string> = {
4	  neutral: "bg-ink-3",
5	  brand: "bg-brand",
6	  ok: "bg-ok",
7	  warn: "bg-warn",
8	  danger: "bg-danger",
9	  info: "bg-info",
10	};
11	
12	/** Usage bars change tone as they fill. Reused by credits, websites and any
13	    other quota so "you are close to the limit" always looks the same. */
14	export function toneForUsage(fraction: number): Tone {
15	  if (fraction >= 0.9) return "danger";
