import { ButtonLink } from "@/components/ui/Button";
import { Badge } from "@/components/ui/Badge";
import { Card, CardHeader } from "@/components/ui/Card";
import { toneForUsage } from "@/components/ui/Progress";
import { Stat } from "@/components/ui/Stat";
import { formatCredits } from "./ledger";

/**
 * The self-imposed spending cap, rendered as STATUS only.
 *
 * Shared by /dashboard/billing and /dashboard/usage so the two can never
 * disagree about the one real limit on this account. It lives under billing/
 * because that is already where the credit vocabulary lives (ledger.ts).
 *
 * It deliberately does NOT contain the form. The form is owned by /settings
 * (app/(portal)/settings/SpendCapForm.tsx) and writes to User.spendCapCredits;
 * a second copy of a control that mutates the user record is exactly how two
 * screens end up disagreeing about what the cap is. Both callers link there.
 *
 * `spent` is passed in rather than fetched here because getSpendCapStatus skips
 * the spend query entirely when the user is uncapped, and both pages need the
 * figure either way.
 */
export function SpendCapPanel({ cap, spent }: { cap: number | null; spent: number }) {
  if (cap === null) {
    return (
      <Card>
        <CardHeader
          title="Spending cap"
          description="The only ceiling on this account is one you set yourself. There is no plan limit to run into."
          action={
            <ButtonLink href="/settings" variant="secondary" size="sm">
              Set a cap
            </ButtonLink>
          }
        />
        <p className="mt-4 text-sm leading-relaxed text-ink-2">
          You haven&apos;t set one. With a cap, builds stop once you&apos;ve spent a number of
          credits you choose in any rolling 30-day period. You&apos;ve spent{" "}
          <span className="k-num font-medium text-ink">{formatCredits(spent)}</span> credits in the
          current window.
        </p>
        <p className="mt-2 text-xs leading-relaxed text-ink-3">
          Rolling, not monthly: each charge stops counting exactly 30 days after it happened, so
          there is no reset day and no cliff where the cap quietly stops protecting you mid-month.
        </p>
      </Card>
    );
  }

  const reached = spent >= cap;
  const remaining = Math.max(0, cap - spent);

  return (
    <Card>
      <CardHeader
        title="Spending cap"
        description="Your own ceiling on credits spent in any rolling 30-day period."
        action={
          <div className="flex items-center gap-2">
            {reached && (
              <Badge tone="warn" dot>
                Cap reached
              </Badge>
            )}
            <ButtonLink href="/settings" variant="secondary" size="sm">
              Change cap
            </ButtonLink>
          </div>
        }
      />
      <div className="mt-5">
        <Stat
          label="Spent in the last 30 days"
          value={formatCredits(spent)}
          unit={`of ${formatCredits(cap)} credits`}
          bar={{ value: Math.min(spent, cap), max: cap }}
          tone={toneForUsage(cap > 0 ? spent / cap : 0)}
          detail={
            reached
              ? "Builds are paused until this drops below your cap, or until you change it. It's your cap — we never raise it for you."
              : `${formatCredits(remaining)} credits left under your cap. It's your cap — we never raise it for you.`
          }
        />
      </div>
      <p className="mt-4 text-xs leading-relaxed text-ink-3">
        Rolling, not monthly: each charge stops counting exactly 30 days after it happened, so there
        is no reset day.
      </p>
    </Card>
  );
}

import { db } from "@/lib/db";
import { MICROS_PER_CREDIT } from "@/lib/credits";

// Aggregations for /dashboard/usage. Everything here is derived from rows that
// already exist — CreditLedger and Build — with no schema change and no
// estimate. If a number cannot be computed from those two tables it is not in
// this file, and the page says so instead of inventing it.
//
// Deliberately absent, because nothing measures them: storage, bandwidth,
// request counts, seats, and anything resembling a plan allowance.
//
// COST BASIS IS NOT EXPOSED. Build.costMicros is our real model spend, which is
// the cost side of the retail prices in lib/stripe.ts. Every figure this module
// returns is in CREDITS; costMicros is only ever used inside an arithmetic
// comparison against what was charged, never returned as money.

const MS_DAY = 24 * 60 * 60 * 1000;

/** Epoch ms for the start of the UTC calendar day containing `d`. */
function utcDayStart(d: Date): number {
  return Date.UTC(d.getUTCFullYear(), d.getUTCMonth(), d.getUTCDate());
}

export type DayBucket = {
  /** Start of the UTC day, epoch ms. */
  ts: number;
  credits: number;
};

/**
 * Credits spent per UTC calendar day over the last `days` days, today included.
 *
 * NOTE the deliberate mismatch with spentInWindow() in lib/credits.ts: that one
 * measures a rolling window to the millisecond because it is what the spend cap
 * enforces. A chart cannot have a half-day bucket at its left edge, so this
 * snaps to UTC day boundaries. The two totals can therefore differ by up to one
 * day's spend, and the page says so rather than presenting them as the same
 * number twice.
 *
 * Row count is bounded by one user's charges in 90 days, so bucketing in JS
 * beats a raw SQL date_trunc that would have to be written per-dialect.
 */
export async function dailySpend(userId: string, days: number): Promise<DayBucket[]> {
  const firstDay = utcDayStart(new Date()) - (days - 1) * MS_DAY;

  const rows = await db.creditLedger.findMany({
    where: { userId, delta: { lt: 0 }, createdAt: { gte: new Date(firstDay) } },
    select: { createdAt: true, delta: true },
  });

  const buckets: DayBucket[] = Array.from({ length: days }, (_, i) => ({
    ts: firstDay + i * MS_DAY,
    credits: 0,
  }));

  for (const row of rows) {
    const index = Math.round((utcDayStart(row.createdAt) - firstDay) / MS_DAY);
    // Defensive: a DST-free UTC calculation should never land outside the
    // array, but a clock skew between Postgres and this process could. A bar
    // silently written past the end of the chart is worse than a dropped one.
    if (index >= 0 && index < days) {
      buckets[index].credits += Math.abs(row.delta);
    }
  }

  return buckets;
}

export type SiteUsage = {
  projectId: string;
  name: string;
  credits: number;
  builds: number;
  lastAt: Date;
};

/**
 * Credits charged, grouped by the website they were charged for.
 *
 * Attribution is real, not inferred: CreditLedger.buildId -> Build.projectId.
 * This groups the Build side because it also carries the build count and the
 * last-charged date, which the ledger alone does not.
 *
 * IT CANNOT SEE DELETED SITES. Project deletion cascades its builds away and
 * SET NULLs CreditLedger.buildId (prisma/schema.prisma), so the charge survives
 * on the statement with nothing attached. The caller reconciles this total
 * against the ledger and shows the difference explicitly — see the page.
 */
export async function siteUsage(userId: string): Promise<SiteUsage[]> {
  const grouped = await db.build.groupBy({
    by: ["projectId"],
    where: { project: { userId }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
    _sum: { creditsCharged: true },
    _count: true,
    _max: { createdAt: true },
  });

  if (grouped.length === 0) return [];

  const projects = await db.project.findMany({
    where: { id: { in: grouped.map((g) => g.projectId) }, userId },
    select: { id: true, name: true },
  });
  const nameById = new Map(projects.map((p) => [p.id, p.name]));

  const rows: SiteUsage[] = [];
  for (const g of grouped) {
    const name = nameById.get(g.projectId);
    const lastAt = g._max.createdAt;
    // A group with no matching project, or no date, means the read raced a
    // delete. Drop it rather than rendering a row with a placeholder name — the
    // reconciliation below folds it into the deleted-sites total instead, which
    // is where it honestly belongs.
    if (name === undefined || lastAt === null) continue;
    rows.push({
      projectId: g.projectId,
      name,
      credits: g._sum.creditsCharged ?? 0,
      builds: g._count,
      lastAt,
    });
  }

  return rows.sort((a, b) => b.credits - a.credits || a.name.localeCompare(b.name));
}

export type NotCharged = {
  failedBuilds: number;
  repairedBuilds: number;
  /** Credits the repair rule absorbed. Conservative — see below. */
  repairWaivedCredits: number;
};

/**
 * The two things Kodely records but never bills: failed builds and repair
 * passes. Both are rules 3 and 4 of the contract in lib/credits.ts, restated as
 * arithmetic on this user's own rows.
 *
 * The waived figure is DERIVED, exactly as lib/credits.ts says it can be:
 * repairAttempts > 0 together with costMicros > creditsCharged * MICROS_PER_CREDIT
 * is "this run was repaired and we absorbed the difference".
 *
 * It understates on purpose. creditsCharged is rounded UP from the billable
 * attempt, so charging-side micros are overstated and the derived difference
 * comes out low. On a page whose entire point is not overclaiming, a saving
 * quoted slightly under the truth is the only acceptable rounding direction.
 */
export async function notCharged(userId: string): Promise<NotCharged> {
  const [failedBuilds, repaired] = await Promise.all([
    db.build.count({ where: { project: { userId }, status: "FAILED" } }),
    db.build.aggregate({
      where: { project: { userId }, status: "SUCCEEDED", repairAttempts: { gt: 0 } },
      _count: true,
      _sum: { costMicros: true, creditsCharged: true },
    }),
  ]);

  const trueMicros = repaired._sum.costMicros ?? 0;
  const chargedMicros = (repaired._sum.creditsCharged ?? 0) * MICROS_PER_CREDIT;

  return {
    failedBuilds,
    repairedBuilds: repaired._count,
    repairWaivedCredits: Math.max(0, Math.floor((trueMicros - chargedMicros) / MICROS_PER_CREDIT)),
  };
}

export type LedgerTotals = {
  /** Every positive delta: the signup grant, paid top-ups, social rewards. */
  added: number;
  /** Every negative delta. Today only chargeForBuild writes one. */
  spent: number;
};

export async function ledgerTotals(userId: string): Promise<LedgerTotals> {
  const [credited, debited] = await Promise.all([
    db.creditLedger.aggregate({ where: { userId, delta: { gt: 0 } }, _sum: { delta: true } }),
    db.creditLedger.aggregate({ where: { userId, delta: { lt: 0 } }, _sum: { delta: true } }),
  ]);
  return {
    added: credited._sum.delta ?? 0,
    spent: Math.abs(debited._sum.delta ?? 0),
  };
}

import { EmptyState } from "@/components/ui/EmptyState";
import { formatCredits } from "../billing/ledger";
import type { DayBucket } from "./data";

/* Credits spent per day, drawn by hand.
   ───────────────────────────────────────────────────────────────────────────
   NO CHARTING DEPENDENCY. This is plain SVG in a Server Component: it ships no
   JavaScript at all, which for a static bar chart is not a compromise — it is
   the better answer.

   THEMING. Every colour is a Tailwind class bound to a design token
   (`fill-brand`, `stroke-hair`, `fill-ink-3`), never an attribute and never a
   hex, so light and dark are handled by the same variable swap as the rest of
   the product. Presentational SVG attributes lose to CSS, which is why the
   classes work at all.

   ACCESSIBILITY. Three channels, in order of who they serve:
     1. A prose summary above the chart — the shape of the data in a sentence,
        for everyone including people who skim.
     2. The <svg> is role="img" with an aria-label carrying that same summary,
        so a screen reader gets the gist instead of 30 unlabelled <rect>s.
     3. A real <table> in a <details>, keyboard-operable, carrying every figure
        the bars encode. The bars are not individually focusable BECAUSE the
        table exists: 30 tab stops that each announce one number is worse than
        one tab stop that opens all of them.
   The chart is also legible at any width — it scales uniformly with its
   viewBox, so no label is ever clipped or squashed. */

const AXIS_DATE = new Intl.DateTimeFormat("en-GB", {
  day: "numeric",
  month: "short",
  timeZone: "UTC",
});

const FULL_DATE = new Intl.DateTimeFormat("en-GB", {
  weekday: "short",
  day: "2-digit",
  month: "short",
  year: "numeric",
  timeZone: "UTC",
});

/** Round a peak up to a round number so the top gridline reads as a real
    quantity ("500") rather than as the maximum sample ("472"). */
function niceCeiling(peak: number): number {
  if (peak <= 0) return 1;
  const magnitude = 10 ** Math.floor(Math.log10(peak));
  for (const step of [1, 1.5, 2, 2.5, 5, 10]) {
    const candidate = step * magnitude;
    if (candidate >= peak) return Math.ceil(candidate);
  }
  return Math.ceil(10 * magnitude);
}

// User-space geometry. The SVG scales uniformly to its container, so these are
// proportions rather than pixels.
const W = 720;
const H = 210;
const PAD_L = 48;
const PAD_R = 10;
const PAD_T = 12;
const PAD_B = 30;
const PLOT_W = W - PAD_L - PAD_R;
const PLOT_H = H - PAD_T - PAD_B;

export function UsageChart({ buckets, days }: { buckets: DayBucket[]; days: number }) {
  const total = buckets.reduce((sum, b) => sum + b.credits, 0);

  if (total === 0 || buckets.length === 0) {
    return (
      <EmptyState
        className="mt-5"
        kind="empty"
        title={`No credits spent in the last ${days} days`}
        body="Nothing has been charged to your account in this window. A build only reaches this chart once it has succeeded and had measured model cost — failed builds are free and never appear."
      />
    );
  }

  const activeDays = buckets.filter((b) => b.credits > 0).length;
  const peak = buckets.reduce((best, b) => (b.credits > best.credits ? b : best), buckets[0]);
  const max = niceCeiling(peak.credits);

  const summary =
    `Credits spent per day over the last ${days} days. ` +
    `${formatCredits(total)} credits in total across ${activeDays} ` +
    `${activeDays === 1 ? "day" : "days"} with any spend. ` +
    `The heaviest day was ${FULL_DATE.format(new Date(peak.ts))} at ` +
    `${formatCredits(peak.credits)} credits.`;

  const slot = PLOT_W / buckets.length;
  const barW = Math.max(2, Math.min(18, slot * 0.62));

  // Three gridlines is the most a 170-unit-tall plot can carry without the
  // labels becoming the loudest thing in it.
  const gridValues = [0, max / 2, max];

  // Four x labels, evenly spaced and always including both ends, so the reader
  // can date any bar by interpolation without 30 overlapping labels.
  const last = buckets.length - 1;
  const tickIndexes = Array.from(
    new Set([0, Math.round(last / 3), Math.round((2 * last) / 3), last]),
  ).filter((i) => i >= 0 && i <= last);

  const y = (value: number) => PAD_T + PLOT_H * (1 - value / max);

  return (
    <figure className="mt-5">
      <figcaption className="text-sm leading-relaxed text-ink-2">
        <span className="k-num font-medium text-ink">{formatCredits(total)}</span> credits over the
        last <span className="k-num font-medium text-ink">{days}</span> days, across{" "}
        <span className="k-num font-medium text-ink">{activeDays}</span>{" "}
        {activeDays === 1 ? "day" : "days"} with any spend. Heaviest day:{" "}
        <span className="k-num font-medium text-ink">{formatCredits(peak.credits)}</span> credits on{" "}
        {FULL_DATE.format(new Date(peak.ts))}.
      </figcaption>

      <svg
        role="img"
        aria-label={summary}
        viewBox={`0 0 ${W} ${H}`}
        className="mt-4 h-auto w-full"
      >
        {gridValues.map((value) => (
          <g key={value}>
            <line
              x1={PAD_L}
              x2={W - PAD_R}
              y1={y(value)}
              y2={y(value)}
              className={value === 0 ? "stroke-line-mid" : "stroke-hair"}
              strokeWidth={1}
            />
            <text
              x={PAD_L - 8}
              y={y(value) + 3.5}
              textAnchor="end"
              fontSize={10}
              className="k-num fill-ink-3"
            >
              {formatCredits(Math.round(value))}
            </text>
          </g>
        ))}

        {buckets.map((b, i) => {
          if (b.credits <= 0) return null;
          // A one-unit floor so a real but tiny day is a visible mark rather
          // than a gap indistinguishable from a day with no spend at all.
          const height = Math.max(1.5, (b.credits / max) * PLOT_H);
          return (
            <rect
              key={b.ts}
              x={PAD_L + slot * (i + 0.5) - barW / 2}
              y={PAD_T + PLOT_H - height}
              width={barW}
              height={height}
              rx={1.5}
              className="fill-brand"
            />
          );
        })}

        {tickIndexes.map((i) => (
          <text
            key={buckets[i].ts}
            x={PAD_L + slot * (i + 0.5)}
            y={H - 10}
            textAnchor={i === 0 ? "start" : i === last ? "end" : "middle"}
            fontSize={10}
            className="k-num fill-ink-3"
          >
            {AXIS_DATE.format(new Date(buckets[i].ts))}
          </text>
        ))}
      </svg>

      <details className="mt-4">
        <summary className="k-focus inline-flex cursor-pointer rounded-sm text-[0.8125rem] font-medium text-ink-2 hover:text-ink">
          Show these {activeDays} {activeDays === 1 ? "day" : "days"} as a table
        </summary>
        <div className="k-scroll-x mt-3 rounded-lg border border-hair">
          <table className="w-full text-left text-sm">
            <caption className="sr-only">
              Credits spent per UTC day over the last {days} days. Days with no spend are omitted.
            </caption>
            <thead>
              <tr className="border-b border-hair">
                <th scope="col" className="k-label px-4 py-2.5 font-semibold">
                  Day (UTC)
                </th>
                <th scope="col" className="k-label px-4 py-2.5 text-right font-semibold">
                  Credits
                </th>
              </tr>
            </thead>
            <tbody className="divide-y divide-hair">
              {buckets
                .filter((b) => b.credits > 0)
                .reverse()
                .map((b) => (
                  <tr key={b.ts}>
                    <td className="k-num px-4 py-2.5 whitespace-nowrap text-ink-2">
                      {FULL_DATE.format(new Date(b.ts))}
                    </td>
                    <td className="k-num px-4 py-2.5 text-right font-medium whitespace-nowrap text-ink">
                      {formatCredits(b.credits)}
                    </td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
        <p className="mt-2 text-xs text-ink-3">
          Days with no spend are left out — {days - activeDays} of the last {days}.
        </p>
      </details>
    </figure>
  );
}

