/* /dashboard/usage — what the credits went ON.
   ───────────────────────────────────────────────────────────────────────────
   The brief for this screen asked for storage, bandwidth, a plan allowance and
   a reset date. None of the four exist (docs/design-system.md, "What does not
   exist"), so none of the four are drawn here. What IS real turns out to be
   more useful anyway: every credit ever charged is a successful build, every
   build belongs to a website, and both facts are already in the database.

   Every figure on this page is in CREDITS. Build.costMicros is real model
   spend — the cost side of the retail prices in lib/stripe.ts — and it is used
   only inside the arithmetic in ./data.ts, never rendered as money. */

// Rolling window options for the chart. A closed table, looked up with
// hasOwnProperty so a query string of "constructor" or "__proto__" resolves to
// a miss rather than to something on Object.prototype.
const RANGES: Record<string, number> = { "30": 30, "90": 90 };
const DEFAULT_RANGE = "30";

function pickRange(params: Record<string, string | string[] | undefined>): {
  key: string;
  days: number;
} {
  const raw = Object.prototype.hasOwnProperty.call(params, "range") ? params.range : undefined;
  // `?range=30&range=90` arrives as an array; there is no sane single answer to
  // that, so it falls through to the default rather than picking one at random.
  const key = typeof raw === "string" ? raw : DEFAULT_RANGE;
  if (Object.prototype.hasOwnProperty.call(RANGES, key)) {
    return { key, days: RANGES[key] };
  }
  return { key: DEFAULT_RANGE, days: RANGES[DEFAULT_RANGE] };
}

export default async function UsagePage({
  searchParams,
}: {
  searchParams: Promise<Record<string, string | string[] | undefined>>;
}) {
  const user = await getCurrentUser();
  if (!user) redirect("/login");

  const range = pickRange(await searchParams);
  const cap = await getSpendCapStatus(user.id);

  const [balance, spent, avgBuildCredits, measuredBuilds, sites, totals, waived, buckets] =
    await Promise.all([
      getBalance(user.id),
      // getSpendCapStatus skips the spend query when the user is uncapped; this
      // page needs the figure either way, and it must be the same query the cap
      // enforces so the two can't disagree.
      cap.cap === null ? spentInWindow(user.id) : Promise.resolve(cap.spent),
      averageBuildCredits(user.id),
      // averageBuildCredits falls back to a global constant when there is no
      // history. That constant is a fine default for "builds remaining" but it
      // is NOT a measurement of this person, so nothing derived from it is
      // shown until this count says there is something real behind it.
      db.build.count({
        where: { project: { userId: user.id }, status: "SUCCEEDED", creditsCharged: { gt: 0 } },
      }),
      siteUsage(user.id),
      ledgerTotals(user.id),
      notCharged(user.id),
      dailySpend(user.id, range.days),
    ]);

  const attributed = sites.reduce((sum, s) => sum + s.credits, 0);
  // Deleting a project cascades its builds away and SET NULLs the ledger's
  // buildId, so the charge outlives the thing it was for. That gap is real and
  // is shown as its own row rather than quietly rounding the percentages.
  const orphaned = Math.max(0, totals.spent - attributed);
  const largest = Math.max(attributed > 0 ? sites[0].credits : 0, orphaned, 1);
  const share = (credits: number) =>
    totals.spent > 0 ? Math.round((credits / totals.spent) * 100) : 0;

  const buildsLeft = measuredBuilds > 0 ? Math.floor(balance / avgBuildCredits) : null;

  return (
    <>
      <SectionHeader
        title="Usage"
        description="Kodely charges per build, not per month. This is every credit you have spent and what it went on."
        action={
          <ButtonLink href="/dashboard/billing" variant="secondary" size="sm">
            Billing &amp; statement
          </ButtonLink>
        }
      />

      {/* ── Where you stand ─────────────────────────────────────────────── */}
      <Card>
        <StatRow>
          <Stat
            label="Credits left"
            value={formatCredits(balance)}
            unit="credits"
            detail={
              balance === 0
                ? "You're out. Nothing expires — this is simply what's left."
                : "Credits never expire, and there is no monthly allowance to use up."
            }
          />
          <Stat
            label="Spent · last 30 days"
            value={formatCredits(spent)}
            unit="credits"
            detail="A rolling window measured to the hour, not a calendar month. There is no reset day."
          />
          <Stat
            label="Your average build"
            value={measuredBuilds > 0 ? formatCredits(avgBuildCredits) : "—"}
            unit={measuredBuilds > 0 ? "credits" : undefined}
            detail={
              measuredBuilds > 0
                ? `Measured across your recent builds — ${formatCredits(measuredBuilds)} charged so far.`
                : "Nothing measured yet. You haven't been charged for a build."
            }
          />
          <Stat
            label="Builds you can afford"
            value={buildsLeft === null ? "—" : formatCredits(buildsLeft)}
            unit={buildsLeft === null ? undefined : "more"}
            detail={
              buildsLeft === null
                ? "Needs at least one charged build of your own before this means anything."
                : "At your own measured average. A bigger site costs more than a smaller one."
            }
          />
        </StatRow>
      </Card>

      {/* ── The one real control over usage ─────────────────────────────── */}
      <div className="mt-4">
        <SpendCapPanel cap={cap.cap} spent={spent} />
      </div>

      {/* ── Usage over time ─────────────────────────────────────────────── */}
      <Card className="mt-4">
        <CardHeader
          title="Credits spent over time"
          description="One bar per UTC day. Only successful, metered builds are charged, so only those appear."
          action={
            <nav aria-label="Chart range" className="flex items-center gap-1">
              {Object.keys(RANGES).map((key) => {
                const current = key === range.key;
                return (
                  <ButtonLink
                    key={key}
                    href={key === DEFAULT_RANGE ? "/dashboard/usage" : `/dashboard/usage?range=${key}`}
                    variant={current ? "soft" : "ghost"}
                    size="xs"
                    aria-current={current ? "page" : undefined}
                    className="k-num"
                  >
                    {key} days
                  </ButtonLink>
                );
              })}
            </nav>
          }
        />

        <UsageChart buckets={buckets} days={range.days} />

        <p className="mt-4 text-xs leading-relaxed text-ink-3">
          These bars are UTC calendar days; the &ldquo;last 30 days&rdquo; figure above is a rolling
          window measured to the hour. The two totals can differ by up to one day&apos;s spend, and
          that is the reason — neither is an estimate.
